10: static bool validate_utf8(const char *b, size_t length) {
11:   const unsigned char *bytes = (const unsigned char *)b;
12:   size_t index = 0;
13: 
14:   while (index < length) {
15:     // Skip full words only when every byte in the word is ASCII. memcpy keeps
16:     // the load valid for unaligned input and the length check prevents overread.
17:     while (length - index >= sizeof(uint64_t)) {
18:       uint64_t word;
19:       memcpy(&word, bytes + index, sizeof(word));
20:       if ((word & UINT64_C(0x8080808080808080)) == 0) {
21:         index += sizeof(word);
22:         continue;
23:       }
24: 
25:       // The word contains a non-ASCII byte. Skip only its ASCII prefix; validate
26:       // the first non-ASCII byte and its sequence with the scalar checks below.
27:       while (index < length && bytes[index] < 0x80) {
28:         ++index;
29:       }
30:       break;
31:     }
32: 
33:     if (index >= length) {
34:       return true;
35:     }
36: 
37:     unsigned char byte1 = bytes[index++];
38:     if (byte1 < 0x80) {
39:       continue;
40:     }
41: 
42:     if (byte1 < 0xE0) {
43:       // Two-byte form.
44:       if (index == length) {
45:         return false;
46:       }
47:       if (byte1 < 0xC2 || (bytes[index++] & 0xC0) != 0x80) {
48:         return false;
49:       }
50:     } else if (byte1 < 0xF0) {
51:       // Three-byte form.
52:       if (length - index < 2) {
53:         return false;
54:       }
55:       unsigned char byte2 = bytes[index++];
56:       if ((byte2 & 0xC0) != 0x80
57:           // Overlong? 5 most significant bits must not all be zero.
58:           || (byte1 == 0xE0 && byte2 < 0xA0)
59:           // Check for illegal surrogate codepoints.
60:           || (byte1 == 0xED && 0xA0 <= byte2)
61:           // Third byte trailing-byte test.
62:           || (bytes[index++] & 0xC0) != 0x80) {
63:         return false;
64:       }
65:     } else {
66:       // Four-byte form.
67:       if (length - index < 3) {
68:         return false;
69:       }
70:       unsigned char byte2 = bytes[index++];
71:       if ((byte2 & 0xC0) != 0x80
72:           // Check that 1 <= plane <= 16.
73:           || (byte1 > 0xF4 || (byte1 == 0xF0 && byte2 < 0x90) || (byte1 == 0xF4 && byte2 > 0x8F))
74:           // Third byte trailing-byte test
75:           || (bytes[index++] & 0xC0) != 0x80
76:           // Fourth byte trailing-byte test
77:           || (bytes[index++] & 0xC0) != 0x80) {
78:         return false;
79:       }
80:     }
81:   }
82:   return true;
83: }
