  const __m128i byte_c1 = _mm_set1_epi8(static_cast<char>(0xc1));
  const __m128i byte_f5 = _mm_set1_epi8(static_cast<char>(0xf5));
  const __m128i byte_ed = _mm_set1_epi8(static_cast<char>(0xed));
  const __m128i byte_e0 = _mm_set1_epi8(static_cast<char>(0xe0));
  const __m128i byte_f0 = _mm_set1_epi8(static_cast<char>(0xf0));
